import React from "react";
import { AuthForm } from "./auth-form";
import { SocialLogin } from "./social-login";

export interface AuthBasicProps extends React.ComponentPropsWithoutRef<"div"> {
    /** The brand name displayed on the card */
    brandName?: string;
    /** Custom logo element */
    logo?: React.ReactNode;
    /** The color of the dotted grid/borders in light mode */
    dotColorLight?: string;
    /** The color of the dotted grid/borders in dark mode */
    dotColorDark?: string;
    /** Whether to show the social login buttons */
    showSocialLogin?: boolean;
}


export default function AuthBasic({
    brandName = "Jack UI",
    logo,
    dotColorLight = "rgba(0, 0, 0, 0.22)",
    dotColorDark = "rgba(255, 255, 255, 0.35)",
    showSocialLogin = true,
    className,
    style,
    ...props
}: AuthBasicProps) {
    const id = React.useId().replace(/:/g, "");
    const instanceClass = `jack-auth-basic-${id}`;

    return (
        <div 
            className={`relative flex min-h-[680px] h-full w-full items-center justify-center p-6 md:p-16 bg-[#f8f9fc] dark:bg-[#09090b] overflow-hidden rounded-[2.5rem] select-none font-mono ${instanceClass} ${className || ""}`}
            style={style}
            {...props}
        >
            {/* Dynamic CSS variables scoped to this component instance */}
            <style dangerouslySetInnerHTML={{ __html: `
                .${instanceClass} {
                    --dot-color: ${dotColorLight};
                }
                .dark .${instanceClass} {
                    --dot-color: ${dotColorDark};
                }
            ` }} />

            {/* Ambient Background Grid Dots */}
            <div 
                className="absolute inset-0 opacity-40 dark:opacity-45 pointer-events-none"
                style={{
                    backgroundImage: "radial-gradient(circle at 1px 1px, var(--dot-color) 1.2px, transparent 0)",
                    backgroundSize: "24px 24px"
                }}
            />

            {/* Ambient Rainbow/Aurora Background Glows */}
            <div 
                className="absolute w-[480px] h-[480px] rounded-full opacity-[0.28] dark:opacity-[0.16] pointer-events-none blur-[90px] select-none"
                style={{
                    background: "conic-gradient(from 0deg, #ff3b30, #ff9500, #ffcc00, #4cd964, #5ac8fa, #007aff, #5856d6, #ff2d55, #ff3b30)"
                }}
            />

            {/* Main Card */}
            <div 
                className="w-full max-w-[380px] sm:w-[380px] bg-white dark:bg-[#0c0c0e] border-[3px] border-dotted rounded-xl p-8 shadow-[0_12px_40px_-10px_rgba(0,0,0,0.03)] dark:shadow-[0_20px_50px_rgba(0,0,0,0.6)] transition-all duration-300 z-10 relative"
                style={{ borderColor: "var(--dot-color)" }}
            >
                
                {/* Header: Brand Identity */}
                <div className="flex items-center gap-3.5 mb-8">
                    {/* Custom logo or sleek default shield brand badge */}
                    {logo ?? (
                        <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-neutral-900 dark:bg-neutral-100 text-white dark:text-neutral-950 shadow-md">
                            <svg className="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
                                <rect x="9" y="11" width="6" height="4" rx="1" />
                            </svg>
                        </div>
                    )}
                    <div className="flex flex-col text-left font-sans">
                        <h2 className="text-base font-bold tracking-tight text-neutral-900 dark:text-white">
                            {brandName}
                        </h2>
                        <span className="text-[10px] text-neutral-400 dark:text-neutral-500 font-mono">
                            Secure Login
                        </span>
                    </div>
                </div>

                {/* Authentication Form */}
                <AuthForm />

                {/* Social Login */}
                {showSocialLogin && (
                    <div className="mt-6 space-y-4">
                        <SocialLogin />
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Loader2 } from "lucide-react";

export function AuthForm() {
    const [isLoading, setIsLoading] = useState(false);

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        setIsLoading(true);

        const formData = new FormData(e.target as HTMLFormElement);
        const email = formData.get("email") as string;
        const password = formData.get("password") as string;

        try {
            await new Promise((resolve) => setTimeout(resolve, 2000));
            console.log("Signing in with:", email, password);
        } catch (error) {
            console.error("Authentication error:", error);
        } finally {
            setIsLoading(false);
        }
    }

    return (
        <form onSubmit={handleSubmit} className="space-y-5" noValidate>
            {/* Input Fields */}
            <div className="space-y-4">
                <div className="space-y-1.5 text-left">
                    <label
                        htmlFor="email"
                        className="text-xs font-semibold uppercase tracking-wider transition-colors"
                        style={{ color: "var(--color-text-primary, oklch(0.556 0 0))" }}
                    >
                        Email
                    </label>
                    <Input
                        type="email"
                        name="email"
                        placeholder="you@example.com"
                        required
                        disabled={isLoading}
                        className="w-full h-11 px-3.5 rounded-xl border transition-all text-sm outline-none focus-visible:ring-2 focus-visible:ring-[oklab(0.140764_0.00120224_-0.00421676_/_0.5)]"
                        style={{ 
                            backgroundColor: "var(--color-surface-muted, #ffffff)", 
                            borderColor: "var(--color-border-default, #e4e4e7)",
                            color: "var(--color-text-tertiary, oklch(0.205 0 0))"
                        }}
                        autoComplete="email"
                    />
                </div>

                <div className="space-y-1.5 text-left">
                    <div className="flex justify-between items-center">
                        <label
                            htmlFor="password"
                            className="text-xs font-semibold uppercase tracking-wider transition-colors"
                            style={{ color: "var(--color-text-primary, oklch(0.556 0 0))" }}
                        >
                            Password
                        </label>
                    </div>
                    <Input
                        type="password"
                        name="password"
                        placeholder="••••••••"
                        required
                        disabled={isLoading}
                        className="w-full h-11 px-3.5 rounded-xl border transition-all text-sm outline-none focus-visible:ring-2 focus-visible:ring-[oklab(0.140764_0.00120224_-0.00421676_/_0.5)]"
                        style={{ 
                            backgroundColor: "var(--color-surface-muted, #ffffff)", 
                            borderColor: "var(--color-border-default, #e4e4e7)",
                            color: "var(--color-text-tertiary, oklch(0.205 0 0))"
                        }}
                    />
                </div>
            </div>

            {/* Submit Button */}
            <Button
                type="submit"
                disabled={isLoading}
                className="relative w-full h-12 text-[15px] font-semibold text-white rounded-2xl transition-all duration-200 cursor-pointer mt-2 border-0"
                style={{
                    background: "linear-gradient(180deg, #2a2a2e 0%, #121214 100%)",
                    boxShadow: "oklch(0.205 0 0) 0px 0px 0px 2px inset, oklab(0.999994 0.0000455678 0.0000200868 / 0.2) 0px 0px 0px 3px inset, rgba(255, 255, 255, 0.2) 0px 0px 10px 0px inset, rgba(0, 0, 0, 0.35) 0px 14px 28px -6px"
                }}
            >
                {isLoading ? (
                    <span className="flex items-center justify-center gap-2">
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Signing in...
                    </span>
                ) : (
                    "Sign in"
                )}
            </Button>
        </form>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Loader2 } from "lucide-react";

export function SocialLogin() {
    const [isGoogleLoading, setIsGoogleLoading] = useState(false);

    async function handleGoogleSignIn() {
        setIsGoogleLoading(true);
        try {
            /**
             * To update with your actual authentication logic
             */
            await new Promise((resolve) => setTimeout(resolve, 1500));
            console.log("Signing in with Google");
        } catch (error) {
            console.error("Google sign-in error:", error);
        } finally {
            setIsGoogleLoading(false);
        }
    }

    function GoogleIcon() {
        return (
            <svg
                className="mr-2 h-4 w-4"
                aria-hidden="true"
                focusable="false"
                data-prefix="fab"
                data-icon="google"
                role="img"
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 488 512"
            >
                <path
                    fill="currentColor"
                    d="M488 261.8C488 403.3 391.1 504 248 504 110.8 504 0 393.2 0 256S110.8 8 248 8c66.8 0 123 24.5 166.3 64.9l-67.5 64.9C258.5 52.6 94.3 116.6 94.3 256c0 86.5 69.1 156.6 153.7 156.6 98.2 0 135-70.4 140.8-106.9H248v-85.3h236.1c2.3 12.7 3.9 24.9 3.9 41.4z"
                ></path>
            </svg>
        );
    }

    return (
        <>
            <div className="relative">
                <div className="absolute inset-0 flex items-center">
                    <Separator className="w-full border-neutral-200 dark:border-neutral-800" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                    <span className="bg-white dark:bg-black px-2 text-neutral-600 dark:text-neutral-400">
                        Or continue with
                    </span>
                </div>
            </div>

            <Button
                variant="outline"
                onClick={handleGoogleSignIn}
                disabled={isGoogleLoading}
                className="w-full h-12 font-medium border border-neutral-200 dark:border-neutral-800 hover:bg-neutral-50 dark:bg-black dark:hover:bg-neutral-900 transition-colors"
            >
                {isGoogleLoading ? (
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                    <GoogleIcon />
                )}
                {isGoogleLoading ? "Connecting..." : "Sign in with Google"}
            </Button>
        </>
    );
}
